// Generated by scaffold-page-from-story from user_stories/S-03-course-detail.yaml
// Story: US-S-03-COURSE-DETAIL
// Role:  all
// Feature: Course detail with syllabus and add to cart
// Goal: As a visitor on a course page I can read what the course covers, expand the syllabus and add the course to my cart so that I can decide and buy in one place.
//
// PRIMARY deterministic page (v128): generated BEFORE convert-pages. It
// compiles by construction, carries the story-spec data-testids, and makes
// the API calls the story expects. convert-pages (LLM) may RESTYLE this file
// in place but is scope-locked: data-testids + default export must survive
// (enforced by scaffold-scope-lock-doctor — violations restore this version).
//
// RESTYLED to mirror design/html/student/S-03-course-detail.html. The visible
// course detail renders the primary GET /api/courses/:slug payload (data1);
// the "Add to cart" button drives the original POST /api/cart/items wiring
// (createItems3). Every original story data-testid is preserved — the two
// carried-over form inputs (ac-3-title / ac-3-content) that the design has no
// home for are kept as hidden inputs inside the buybox so createItems3 still
// finds them, and the raw ac-1 detail dump lives in the sr-only wiring block.

import { useEffect, useMemo, useState } from 'react';
import { Link, useParams } from 'react-router';
import { useTranslation } from 'react-i18next';
import { useAppDispatch } from '~/hooks/useAppDispatch';
import { getCourseBySlug } from '~/services/httpServices/catalogueService';
import { course_level } from '~/enums/course-level.enum';
import { addItem } from '~/services/httpServices/cartManagementService';
import { toast } from '~/lib/toast';
import { getApiErrorMessage } from '~/utils/apiError';
import type { Course } from '~/types/course';
import type { Lesson } from '~/types/lesson';
import type { CourseDetail, SyllabusSection } from '~/types/view-models';
import { ChevronDown, ChevronRight, FileText, HelpCircle as PlayCircle  /* scaffold-lucide-icon-doctor: hallucinated → HelpCircle */, Star } from 'lucide-react';

/** The detail endpoint embeds relations the flat Course type does not
 *  guarantee; widen locally rather than reaching for `any`. */

const LEVEL_LABEL: Record<course_level, string> = {
  [course_level.BEGINNER]: 'Beginner',
  [course_level.INTERMEDIATE]: 'Intermediate',
  [course_level.ADVANCED]: 'Advanced',
};

/** Detail body may be the course object itself or a { data } envelope. */
function extractCourse(payload: unknown): CourseDetail | null {
  if (!payload || typeof payload !== 'object') return null;
  const p = payload as Record<string, unknown>;
  if (typeof p.id === 'string') return p as unknown as CourseDetail;
  if (p.data && typeof p.data === 'object') {
    const d = p.data as Record<string, unknown>;
    if (typeof d.id === 'string') return d as unknown as CourseDetail;
  }
  return null;
}

export default function CourseDetailPage() {
  const { t } = useTranslation('common');
  const dispatch = useAppDispatch();

  const [data1, setData1] = useState<unknown>(null);
  const [loading1, setLoading1] = useState<boolean>(true);
  const [error1, setError1] = useState<string | null>(null);

  // Course detail — GET /api/courses/:slug via the catalogue read thunk.
  //
  // The slug comes from the URL. It was hardcoded to one seeded course, so every card in the
  // catalogue opened the SAME course detail no matter which one was clicked — and the route
  // itself was registered at that literal slug, so no other course had a URL at all.
  const __routeParams = useParams() as Record<string, string | undefined>;
  const slug = __routeParams.slug ?? '';
  useEffect(() => {
    if (!slug) return;
    let cancelled = false;
    setLoading1(true);
    setError1(null);
    dispatch(getCourseBySlug(slug)).unwrap()
      .then((d) => { if (!cancelled) setData1(d); })
      .catch((e: unknown) => { if (!cancelled) setError1(e instanceof Error ? e.message : 'Failed to load'); })
      .finally(() => { if (!cancelled) setLoading1(false); });
    return () => { cancelled = true; };
  }, [dispatch, slug]);

  const course = useMemo<CourseDetail | null>(() => extractCourse(data1), [data1]);

  const [loading3, setLoading3] = useState<boolean>(false);
  const createItems3 = async () => {
    // AddCartItemDto accepts only { courseId } and rejects unknown keys
    // (forbidNonWhitelisted). Send just the courseId — never the DOM-swept ac-3
    // inputs (hidden title/content would 400 if ever populated).
    if (course?.id == null) return;
    setLoading3(true);
    try {
      await addItem({ courseId: course.id });
      toast.success(t('courseDetail.addSuccess', 'Added to your cart'));
    } catch (err) {
      toast.error(getApiErrorMessage(err, t('courseDetail.addFailure', 'Could not add this course to your cart')));
    } finally {
      setLoading3(false);
    }
  };

  const [openIdx, setOpenIdx] = useState<number>(0);

  const sections = useMemo<SyllabusSection[]>(
    () => (course && Array.isArray(course.sections) ? course.sections : []),
    [course],
  );

  const sectionLessons = (s: SyllabusSection): Lesson[] => {
    if (Array.isArray(s.lessons)) return s.lessons;
    if (course && Array.isArray(course.lessons)) return course.lessons.filter((l) => l.sectionId === s.id);
    return [];
  };

  const category = course?.category?.name ?? '';
  const levelLabel = course?.level != null ? (LEVEL_LABEL[course.level as course_level] ?? '') : '';
  const hours = course?.durationMinutes != null ? Math.round(course.durationMinutes / 60) : null;
  const instructor = course?.instructor ?? null;
  const instructorId = instructor?.id ?? course?.instructorId ?? '';

  return (
    <div className="mx-auto max-w-[1240px] px-[24px] py-[32px]" data-testid="s-03-course-detail-page">
      {/* breadcrumb — page content nav (RULE-F13 allows breadcrumbs) */}
      <nav
        className="mb-[24px] flex items-center gap-[8px] text-[14px] text-[var(--c-muted)]"
        aria-label={t('courseDetail.breadcrumb', 'Breadcrumb')}
      >
        <Link to="/" className="text-[var(--c-body)] hover:text-[var(--c-primary)]" data-testid="s-03-course-detail-home-link">
          {t('courseDetail.home', 'Home')}
        </Link>
        <ChevronRight className="h-4 w-4" aria-hidden="true" />
        <Link to="/courses" className="text-[var(--c-body)] hover:text-[var(--c-primary)]" data-testid="s-03-course-detail-crumb-courses">
          {t('courseDetail.courses', 'Courses')}
        </Link>
      </nav>

      <main data-testid="s-03-course-detail-main">
        {loading1 && (
          <div className="grid grid-cols-1 gap-[24px] [@media(min-width:900px)]:grid-cols-[2fr_1fr]" data-testid="s-03-course-detail-ac-1-loading">
            <div className="space-y-[24px]">
              <div className="h-[40px] w-2/3 animate-pulse rounded-[8px] bg-[var(--c-surface-soft)]" />
              <div className="h-[280px] w-full animate-pulse rounded-[8px] bg-[var(--c-surface-soft)]" />
              <div className="h-[160px] w-full animate-pulse rounded-[8px] bg-[var(--c-surface-soft)]" />
            </div>
            <div className="h-[320px] w-full animate-pulse rounded-[8px] bg-[var(--c-surface-soft)]" />
          </div>
        )}

        {!loading1 && error1 && (
          <div
            className="rounded-[8px] border border-[var(--c-hairline)] bg-[var(--c-surface)] p-[24px] text-center"
            data-testid="s-03-course-detail-ac-1-error"
          >
            <p className="m-0 text-[15px] text-[var(--c-error)]">
              {t('courseDetail.loadError', 'We could not load this course. Please try again.')}
            </p>
            <button
              type="button"
              onClick={() => window.location.reload()}
              className="mt-[16px] inline-flex min-h-[44px] cursor-pointer items-center justify-center rounded-[6px] border border-transparent bg-[var(--c-primary)] px-[24px] py-[8px] text-[15px] font-semibold text-[var(--c-on-primary)] hover:bg-[var(--c-primary-active)]"
              data-testid="s-03-course-detail-retry"
            >
              {t('courseDetail.retry', 'Try again')}
            </button>
          </div>
        )}

        {!loading1 && !error1 && !course && (
          <div
            className="rounded-[8px] border border-[var(--c-hairline)] bg-[var(--c-surface)] p-[24px] text-center"
            data-testid="s-03-course-detail-empty"
          >
            <p className="m-0 text-[15px] text-[var(--c-muted)]">
              {t('courseDetail.empty', 'This course is not available.')}
            </p>
          </div>
        )}

        {!loading1 && !error1 && course && (
          <div data-testid="s-03-course-detail-ac-1">
            <div className="grid grid-cols-1 items-start gap-[24px] [@media(min-width:900px)]:grid-cols-[2fr_1fr]" data-testid="s-03-course-detail-ac-1-detail">
              {/* left column */}
              <div className="space-y-[24px]">
                {/* header */}
                <div className="space-y-[8px]">
                  {category && (
                    <span className="inline-flex w-fit items-center rounded-full bg-[var(--c-primary-soft)] px-[10px] py-[4px] text-[12px] font-medium tracking-[0.2px] text-[var(--c-primary-text)]">
                      {category}
                    </span>
                  )}
                  <h1
                    className="m-0 text-[32px] font-bold leading-[1.2] tracking-[-0.3px] text-[var(--c-ink)]"
                    data-testid="s-03-course-detail-heading"
                  >
                    {course.title ?? ''}
                  </h1>
                  <div className="flex flex-wrap items-center gap-[16px]">
                    <span className="inline-flex items-center gap-[4px] text-[14px] font-medium text-[var(--c-ink)]">
                      <Star className="h-4 w-4 text-[var(--c-primary-text)]" aria-hidden="true" />
                      {(course.ratingAvg ?? 0).toFixed(1)}
                    </span>
                    <span className="text-[14px] text-[var(--c-muted)]">
                      {(course.studentCount ?? 0).toLocaleString()} {t('courseDetail.students', 'students')}
                    </span>
                    {hours != null && (
                      <span className="text-[14px] text-[var(--c-muted)]">
                        {hours} {t('courseDetail.hours', 'hours')}
                      </span>
                    )}
                    {levelLabel && (
                      <span className="inline-flex items-center rounded-full bg-[var(--c-surface-soft)] px-[10px] py-[4px] text-[12px] font-medium tracking-[0.2px] text-[var(--c-success)]">
                        {levelLabel}
                      </span>
                    )}
                  </div>
                </div>

                {/* media */}
                <div className="overflow-hidden rounded-[8px] [aspect-ratio:16/9] [background:var(--media-fallback)]">
                  {course.thumbnailUrl && (
                    <img className="block h-full w-full object-cover" src={course.thumbnailUrl} alt={course.title ?? ''} />
                  )}
                </div>

                {/* instructor — ac-4 (visitor clicks the instructor name) */}
                <div data-testid="s-03-course-detail-ac-4">
                  <h2 className="mb-[12px] text-[20px] font-semibold leading-[1.3] text-[var(--c-ink)]">
                    {t('courseDetail.instructor', 'Your instructor')}
                  </h2>
                  <div className="flex items-center gap-[12px] rounded-[8px] border border-[var(--c-hairline)] bg-[var(--c-surface)] p-[24px] shadow-[var(--shadow-1)]">
                    <span className="block h-[64px] w-[64px] flex-none overflow-hidden rounded-full [background:var(--c-surface-soft)]">
                      {instructor?.avatarUrl && (
                        <img className="block h-full w-full object-cover" src={instructor.avatarUrl} alt={instructor?.name ?? ''} />
                      )}
                    </span>
                    <span className="flex flex-col">
                      <Link
                        to={`/instructors/${instructorId}`}
                        className="text-[16px] font-semibold text-[var(--c-ink)] hover:text-[var(--c-primary)]"
                        data-testid="s-03-course-detail-instructor-link"
                      >
                        {instructor?.name ?? ''}
                      </Link>
                      <span className="text-[14px] text-[var(--c-muted)]">
                        {instructor?.headline ?? instructor?.title ?? ''}
                        {instructor?.courseCount != null
                          ? ` · ${instructor.courseCount} ${t('courseDetail.courses', 'courses')}`
                          : ''}
                      </span>
                    </span>
                  </div>
                </div>

                {/* syllabus — ac-2 (visitor expands a syllabus section) */}
                <div data-testid="s-03-course-detail-ac-2">
                  <h2 className="mb-[12px] text-[20px] font-semibold leading-[1.3] text-[var(--c-ink)]">
                    {t('courseDetail.syllabus', 'Course syllabus')}
                  </h2>
                  {sections.length === 0 ? (
                    <div className="rounded-[8px] border border-[var(--c-hairline)] bg-[var(--c-surface)] p-[16px] text-[14px] text-[var(--c-muted)]">
                      {t('courseDetail.syllabusEmpty', 'The syllabus for this course is coming soon.')}
                    </div>
                  ) : (
                    <div className="divide-y divide-[var(--c-hairline)] overflow-hidden rounded-[8px] border border-[var(--c-hairline)] bg-[var(--c-surface)]">
                      {sections.map((section, i) => {
                        const open = openIdx === i;
                        return (
                          <div key={section.id ?? i}>
                            <button
                              className="flex w-full items-center justify-between gap-[8px] px-[16px] py-[14px] text-left text-[15px] font-semibold text-[var(--c-ink)] hover:bg-[var(--c-surface-soft)]"
                              type="button"
                              aria-expanded={open}
                              onClick={() => setOpenIdx((cur) => (cur === i ? -1 : i))}
                              data-testid={`s-03-course-detail-syllabus-section-${i}`}
                            >
                              <span>{`${i + 1}. ${section.title ?? ''}`}</span>
                              <ChevronDown aria-hidden="true" />
                            </button>
                            {open && (
                              <ul className="px-[16px] pb-[12px]">
                                {sectionLessons(section).map((lesson, li) => (
                                  <li
                                    key={lesson.id ?? li}
                                    className="flex items-center gap-[12px] border-t border-[var(--c-hairline)] py-[8px]"
                                  >
                                    {lesson.videoUrl ? (
                                      <PlayCircle className="h-4 w-4 flex-none text-[var(--c-primary-text)]" aria-hidden="true" />
                                    ) : (
                                      <FileText className="h-4 w-4 flex-none text-[var(--c-primary-text)]" aria-hidden="true" />
                                    )}
                                    <span className="flex-1 text-[14px] text-[var(--c-body)]">{lesson.title ?? ''}</span>
                                    <span className="text-[12px] font-medium tracking-[0.2px] text-[var(--c-muted)]">
                                      {lesson.durationMinutes != null ? `${lesson.durationMinutes}m` : ''}
                                    </span>
                                  </li>
                                ))}
                              </ul>
                            )}
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>

                {/* about */}
                <div>
                  <h2 className="mb-[12px] text-[20px] font-semibold leading-[1.3] text-[var(--c-ink)]">
                    {t('courseDetail.about', 'About this course')}
                  </h2>
                  <p className="m-0 text-[15px] leading-[1.6] text-[var(--c-body)]">
                    {course.description ?? course.summary ?? ''}
                  </p>
                </div>
              </div>

              {/* buybox — ac-3 (signed-in student clicks Add to cart) */}
              <aside className="lg:sticky lg:top-[24px]">
                <div
                  className="space-y-[16px] rounded-[8px] border border-[var(--c-hairline)] bg-[var(--c-surface)] p-[24px] shadow-[var(--shadow-2)]"
                  data-testid="s-03-course-detail-ac-3"
                >
                  {/* carried-over story inputs — no home in the design, kept hidden so createItems3 still resolves them */}
                  <input name="title" type="hidden" data-testid="s-03-course-detail-ac-3-title" />
                  <input name="content" type="hidden" data-testid="s-03-course-detail-ac-3-content" />

                  <div>
                    <span className="text-[24px] font-bold text-[var(--c-primary-text)]">
                      {course.price != null ? `$${course.price}` : ''}
                    </span>
                    {course.compareAtPrice != null && (
                      <span className="ml-[8px] text-[14px] font-normal text-[var(--c-muted)] line-through">
                        ${course.compareAtPrice}
                      </span>
                    )}
                  </div>

                  <button
                    className="flex min-h-[44px] w-full cursor-pointer items-center justify-center rounded-[6px] border border-transparent bg-[var(--c-primary)] px-[24px] py-[12px] text-[15px] font-semibold text-[var(--c-on-primary)] hover:bg-[var(--c-primary-active)] disabled:opacity-50"
                    type="button"
                    onClick={createItems3}
                    disabled={loading3}
                    data-testid="s-03-course-detail-ac-3-action"
                  >
                    {loading3 ? t('courseDetail.adding', 'Adding…') : t('courseDetail.addToCart', 'Add to cart')}
                  </button>

                  <Link
                    to="/checkout"
                    className="flex min-h-[44px] w-full cursor-pointer items-center justify-center rounded-[6px] border border-[var(--c-hairline-strong)] bg-[var(--c-surface)] px-[24px] py-[12px] text-[15px] font-semibold text-[var(--c-ink)] hover:bg-[var(--c-surface-soft)]"
                    data-testid="s-03-course-detail-buy-now"
                  >
                    {t('courseDetail.buyNow', 'Buy now')}
                  </Link>

                  <div className="h-px w-full bg-[var(--c-hairline)]" />

                  <p className="m-0 text-[16px] font-semibold text-[var(--c-ink)]">
                    {t('courseDetail.included', 'What is included')}
                  </p>
                  <div className="flex items-center gap-[12px]">
                    <span className="flex h-[24px] w-[24px] flex-none items-center justify-center rounded-full bg-[var(--c-primary-soft)] text-[12px] font-semibold text-[var(--c-primary-text)]">1</span>
                    <span className="text-[14px] text-[var(--c-body)]">
                      {`${hours ?? 0} ${t('courseDetail.hoursOfVideo', 'hours of video')}`}
                    </span>
                  </div>
                  <div className="flex items-center gap-[12px]">
                    <span className="flex h-[24px] w-[24px] flex-none items-center justify-center rounded-full bg-[var(--c-primary-soft)] text-[12px] font-semibold text-[var(--c-primary-text)]">2</span>
                    <span className="text-[14px] text-[var(--c-body)]">
                      {t('courseDetail.includedSheets', 'Downloadable lecture sheets')}
                    </span>
                  </div>
                  <div className="flex items-center gap-[12px]">
                    <span className="flex h-[24px] w-[24px] flex-none items-center justify-center rounded-full bg-[var(--c-primary-soft)] text-[12px] font-semibold text-[var(--c-primary-text)]">3</span>
                    <span className="text-[14px] text-[var(--c-body)]">
                      {t('courseDetail.includedAccess', 'Six months of recording access')}
                    </span>
                  </div>
                </div>
              </aside>
            </div>
          </div>
        )}
      </main>

      {/*
        Story acceptance-criteria wiring — preserved per scope-lock. The detail
        above is the on-screen design; this sr-only block keeps the original
        raw payload dump so the ac-1-detail data-testid survives without
        duplicating the visible UI.
      */}
      <div className="sr-only" data-testid="s-03-course-detail-wiring">
        {!loading1 && !error1 && course && (
          <dl data-testid="s-03-course-detail-ac-1-detail-raw">
            <div><dt>title</dt><dd>{course.title ?? ''}</dd></div>
            <div><dt>slug</dt><dd>{course.slug ?? ''}</dd></div>
            <div><dt>price</dt><dd>{course.price ?? ''}</dd></div>
            <div><dt>level</dt><dd>{course.level ?? ''}</dd></div>
          </dl>
        )}
      </div>
    </div>
  );
}
